function walk(d, acc = []) {
  for (const entry of readdirSync(d, { withFileTypes: true })) {
    const full = join(d, entry.name)
    if (entry.isDirectory()) {
      walk(full, acc)
    } else if (entry.name.endsWith('.html') && entry.name !== '404.html') {
      acc.push(full)
    }
  }
  return acc
}
